// Adapted from: Koleda (Google) 2016 'send an insertDimension and updateCells request in a single batch'
// + AppendCells/InsertDimension/UpdateCells field docs. Runs server-side only.
import { google } from 'googleapis';

export async function writeVote(sheets, spreadsheetId, votesSheetId, vote) {
  const { rugId, value, visitorHash, ts } = vote; // value: 'like' | 'dislike'
  const cell = (v) =>
    typeof v === 'number'
      ? { userEnteredValue: { numberValue: v } }
      : { userEnteredValue: { stringValue: String(v) } };

  await sheets.spreadsheets.batchUpdate({
    spreadsheetId,
    requestBody: {
      requests: [
        {
          insertDimension: {
            // "Inserts rows or columns in a sheet at a particular index"; both indexes must be bounded
            range: { sheetId: votesSheetId, dimension: 'ROWS', startIndex: 1, endIndex: 2 },
            inheritFromBefore: false,
          },
        },
        {
          updateCells: {
            // "Updates all cells in a range with new data"
            start: { sheetId: votesSheetId, rowIndex: 1, columnIndex: 0 },
            rows: [{ values: [cell(ts), cell(rugId), cell(value), cell(visitorHash)] }],
            fields: 'userEnteredValue',
          },
        },
      ],
    },
  });
  // batchUpdate doc: "it is guaranteed that the updates in the request will be applied together atomically"
}

