function doPost(e) {
  const body = JSON.parse(e.postData.contents); // e.postData.contents = "The content text of the POST body"
  const lock = LockService.getScriptLock();       // "prevents any user from concurrently running a section of code"
  try {
    lock.waitLock(10000);                         // throws after 10 s
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ ok: false, error: 'busy' }))
      .setMimeType(ContentService.MimeType.JSON);
  }
  try {
    const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Votes');
    sheet.appendRow([new Date(), body.rugId, body.value, body.visitorHash]);
    SpreadsheetApp.flush();                       // "Applies all pending Spreadsheet changes."
  } finally {
    lock.releaseLock();
  }
  return ContentService.createTextOutput(JSON.stringify({ ok: true }))
    .setMimeType(ContentService.MimeType.JSON);
}
